using System;using System.Collections.Generic;using UnityEngine;using UnityEditor;
public static class DrpgPhase6FixtureBuilder {
 const string Folder="Assets/Resources/DrpgPhase6Tests";
 static T Asset<T>(string name)where T:ScriptableObject{var path=Folder+"/"+name+".asset";var value=AssetDatabase.LoadAssetAtPath<T>(path);if(value==null){value=ScriptableObject.CreateInstance<T>();AssetDatabase.CreateAsset(value,path);}return value;}
 [MenuItem("Editor/DRPG/Fase 6/Preparar mapas independientes")]
 public static string Build(){if(EditorApplication.isPlaying)throw new InvalidOperationException("Salir de Play Mode");if(!AssetDatabase.IsValidFolder(Folder))AssetDatabase.CreateFolder("Assets/Resources","DrpgPhase6Tests");
  var a=Asset<DungeonMapSettings>("FloorA");var b=Asset<DungeonMapSettings>("FloorB");var zone=Asset<EnemyZoneSettings>("Enemies");EditorUtility.CopySerialized(EnemyZoneSettings.Current,zone);zone.maximumEnemies=10;zone.minimumLevel=zone.maximumLevel=1;
  foreach(var map in new[]{a,b}){map.mapId=map==a?"phase6.fixture.a":"phase6.fixture.b";map.rows=new[]{"#########","#.......#","#.......#","#.......#","#.......#","#.......#","#########"};map.includeLegacyObjects=false;map.startCell=new Vector2Int(1,1);map.startHeading=0;map.entities=Asset<DungeonEntitySettings>(map.name+"Objects");map.entities.objects.Clear();map.regions=Asset<DungeonRegionSettings>(map.name+"Regions");map.regions.legacyPlacements=false;map.regions.initialRandomPerZone=0;var region=new DungeonRegion{id=map.mapId+".zone",enemies=zone};for(int y=1;y<6;y++)for(int x=1;x<8;x++)region.cells.Add(new Vector2Int(x,y));map.regions.regions=new[]{region};map.regions.placedEnemies=new PlacedEnemyDefinition[0];map.eventIds=new[]{"phase6.victory.done"};}
  var inventory=Resources.Load<CombatInventorySettings>("Combat/CombatInventorySettings");string potion=inventory.items[0].id;
  var gate=Asset<DungeonInteractionSettings>("ChestCondition");gate.id="phase6.chest.condition";gate.groups=new List<DungeonConditionGroup>{new DungeonConditionGroup{conditions=new List<DungeonCondition>{new DungeonCondition{kind=DungeonConditionKind.Item,targetId="key.red"}}}};gate.actions.Clear();
  var table=Asset<DungeonChestRewardTable>("SecondaryTable");table.id="phase6.table";table.randomRolls=2;table.guaranteed=new[]{new InventoryItemRecord{itemId=potion,quantity=2}};table.secondary=new[]{new DungeonChestRewardEntry{itemId=potion,minimum=1,maximum=2,weight=1}};
  a.entities.objects.Add(new DungeonMapEntity{id="phase6.chest",kind=DungeonEntityKind.Chest,cell=new Vector2Int(2,2),contentId="key.red",quantity=1,chestRewards=table});a.entities.objects.Add(new DungeonMapEntity{id="phase6.story",kind=DungeonEntityKind.Chest,chestKind=DungeonChestKind.KeyItem,cell=new Vector2Int(4,2),contentId="key.green",quantity=1,chestRewards=table});
  var gated=Asset<DungeonChestRewardTable>("ConditionalTable");EditorUtility.CopySerialized(table,gated);gated.id="phase6.conditional.table";gated.conditions=gate;a.entities.objects.Add(new DungeonMapEntity{id="phase6.conditional",kind=DungeonEntityKind.Chest,cell=new Vector2Int(6,2),chestRewards=gated});
  var half=Asset<DungeonInteractionSettings>("BossHalf");half.id="phase6.boss.half";half.once=true;half.groups.Clear();half.actions=new List<DungeonEventAction>{new DungeonEventAction{id="phase6.half.reward",kind=DungeonEventActionKind.Reward,targetId=potion,quantity=1}};
  var victory=Asset<DungeonInteractionSettings>("BossVictory");victory.id="phase6.boss.victory";victory.once=true;victory.groups.Clear();victory.actions=new List<DungeonEventAction>{new DungeonEventAction{id="phase6.victory.flag",kind=DungeonEventActionKind.CompleteEvent,targetId="phase6.victory.done"},new DungeonEventAction{id="phase6.victory.reward",kind=DungeonEventActionKind.Reward,targetId=potion,quantity=1}};
  var boss=Asset<DungeonBossProfile>("BossProfile");boss.id="phase6.boss.profile";boss.phases=new[]{new DungeonBossPhase{id="half",maximumHealthFraction=.5f,onEntered=half}};boss.onVictory=victory;
  a.regions.placedEnemies=new[]{new PlacedEnemyDefinition{id="phase6.boss",speciesId="Tapaku",cell=new Vector2Int(6,4),randomLevel=false,fixedLevel=1,category=PlacedEnemyCategory.Boss,unique=true,respawn=false,countsTowardLimit=false,holdPosition=true,bossProfile=boss}};
  foreach(var map in new[]{a,b}){EditorUtility.SetDirty(map);EditorUtility.SetDirty(map.entities);EditorUtility.SetDirty(map.regions);}foreach(var value in new ScriptableObject[]{zone,gate,table,gated,half,victory,boss})EditorUtility.SetDirty(value);AssetDatabase.SaveAssets();return "Phase 6 fixtures ready";
 }
}
